#!/usr/bin/env python3
"""Build concise issue-cohort tables from the exhaustive per-member assessment."""
import csv,json,collections
from pathlib import Path
OUT=Path(__file__).resolve().parent
rows=json.loads((OUT/'crosswalk-2016-source-to-csd-assessment.json').read_text())['results']
no_name=[r for r in rows if r['inherited_2021_screen_flags']['no_exact_2021_name']]
ambiguous=[r for r in rows if r['inherited_2021_screen_flags']['multiple_exact_2021_names']]
low=[r for r in rows if r['inherited_2021_screen_flags']['best_2021_overlap_below_95']]
source_extent=[r for r in rows if r['official_2016_csd_match']['source_covered_pct']<95]
target_extent=[r for r in rows if r['official_2016_csd_match']['csd_covered_pct']<95]
either_extent=[r for r in rows if r['official_2016_csd_match']['source_covered_pct']<95 or r['official_2016_csd_match']['csd_covered_pct']<95]
old_new_extent=[r for r in low if r['official_2016_to_2021_candidate_overlap_2016_covered_pct']<95 or r['official_2016_to_2021_candidate_overlap_2021_covered_pct']<95]

def name_status(r):
 if r['official_transition_status']=='direct_successor_in_official_change_table': return 'complete_annexation_to_existing_2021_csd'
 if any(e['Gaining Change Code Description'].casefold()=='name change' for e in r['relevant_official_change_table_rows']): return 'official_table_name_change_same_csd_uid'
 if '*' in r['source_name']: return 'source_label_shortened_with_asterisk'
 if 'Ã' in r['source_name']: return 'source_text_encoding_mismatch'
 return 'same_csd_uid_current_name_change_not_listed_in_table'
name_findings=[]
for r in no_name:
 name_findings.append({'source_shape_id':r['source_shape_id'],'source_name_as_delivered':r['source_name'],'official_2016_csd_uid':r['selected_2016_csd_uid'],'official_2016_csd_name':r['selected_2016_csd_name'],'current_2021_csd_uid':r['candidate_2021_csd_uid_from_485'],'current_2021_csd_name':r['candidate_2021_csd_name_from_485'],'status':name_status(r),'table_rows':[{'csv_line':e['csv_line'],'effective_date':e['Effective Date'],'file_number':e['File Number'],'gaining_name':e['Gaining CSDname'],'gaining_description':e['Gaining Change Code Description'],'losing_name':e['Losing CSDname'],'losing_description':e['Losing Change Code Description']} for e in r['relevant_official_change_table_rows'] if e['Gaining Change Code Description'].casefold()=='name change' or r['official_transition_status']=='direct_successor_in_official_change_table']})
counts={k:sum(x['status']==k for x in name_findings) for k in sorted({x['status'] for x in name_findings})}
assert len(name_findings)==20 and counts=={'complete_annexation_to_existing_2021_csd':2,'official_table_name_change_same_csd_uid':10,'same_csd_uid_current_name_change_not_listed_in_table':1,'source_label_shortened_with_asterisk':6,'source_text_encoding_mismatch':1},counts
for r in ambiguous:
 assert len(r['same_name_2021_candidates_in_parent_cd'])==r['name_matches_2021_csd_within_cd']>1
 assert any(x['csduid']==r['candidate_2021_csd_uid_from_485'] for x in r['same_name_2021_candidates_in_parent_cd'])
assert len(ambiguous)==5 and len(low)==33 and len(source_extent)==17 and len(target_extent)==134 and len(either_extent)==141 and len(old_new_extent)==16
assert sum(bool(r['relevant_official_change_table_rows']) for r in old_new_extent)==14
csv_cols=['source_shape_id','source_name','location_id','location_name','parent_cd_uid','source_2016_csd_uid','source_2016_csd_name','source_2016_csd_type','source_2016_source_coverage_pct','statcan_2016_csd_coverage_pct','current_2021_csd_uid','current_2021_csd_name','current_2021_csd_type','legacy_name_match_count','prior_2021_overlap_pct','recomputed_2021_overlap_pct','low_overlap_below_50','current_same_name_candidates','official_2016_to_2021_old_covered_pct','official_2016_to_2021_new_covered_pct','successor_csd_uids','transition_csv_lines','transition_effective_dates','source_geometry_type','source_geometry_part_count','extent_status','extent_assessment']
with open(OUT/'exception-review.csv','w',encoding='utf-8',newline='') as f:
 w=csv.DictWriter(f,fieldnames=csv_cols,lineterminator='\n');w.writeheader()
 for r in rows:
  flags=r['inherited_2021_screen_flags'];g=r['official_2016_csd_match']
  if not any(flags.values()) and g['source_covered_pct']>=95 and g['csd_covered_pct']>=95:continue
  w.writerow({'source_shape_id':r['source_shape_id'],'source_name':r['source_name'],'location_id':r['location_id'],'location_name':r['location_name'],'parent_cd_uid':r['current_parent_cd_uid'],'source_2016_csd_uid':r['selected_2016_csd_uid'],'source_2016_csd_name':r['selected_2016_csd_name'],'source_2016_csd_type':r['selected_2016_csd_type'],'source_2016_source_coverage_pct':g['source_covered_pct'],'statcan_2016_csd_coverage_pct':g['csd_covered_pct'],'current_2021_csd_uid':r['candidate_2021_csd_uid_from_485'],'current_2021_csd_name':r['candidate_2021_csd_name_from_485'],'current_2021_csd_type':r['current_2021_csd_type'],'legacy_name_match_count':r['name_matches_2021_csd_within_cd'],'prior_2021_overlap_pct':r['prior_overlap_pct'],'recomputed_2021_overlap_pct':r['recomputed_source_to_2021_candidate_overlap_pct'],'low_overlap_below_50':flags['best_2021_overlap_below_50'],'current_same_name_candidates':json.dumps(r['same_name_2021_candidates_in_parent_cd'],ensure_ascii=False,separators=(',',':')),'official_2016_to_2021_old_covered_pct':r['official_2016_to_2021_candidate_overlap_2016_covered_pct'],'official_2016_to_2021_new_covered_pct':r['official_2016_to_2021_candidate_overlap_2021_covered_pct'],'successor_csd_uids':';'.join(r['direct_successor_csd_uids_from_change_table']),'transition_csv_lines':';'.join(str(e['csv_line']) for e in r['relevant_official_change_table_rows']),'transition_effective_dates':';'.join(sorted({e['Effective Date'] for e in r['relevant_official_change_table_rows']})),'source_geometry_type':r['source_geometry_type'],'source_geometry_part_count':r['source_geometry_part_count'],'extent_status':r['extent_status'],'extent_assessment':r['extent_assessment']})
summary={'assigned_subjects':376,'original_flag_counts':{'no_exact_2021_name':20,'multiple_same_name_2021_candidates':5,'best_overlap_below_95':33,'best_overlap_below_50':3,'union_subject_count':58},'all_376_assessments_have_distinct_2016_csd_uid':True,'all_376_current_2021_candidate_ids_verified_against_official_2021_file':True,'all_376_2016_and_2021_parent_cd_codes_match_inherited_current_parent':True,'crosswalk':{'same_csd_uid_across_2016_2021':374,'explicit_complete_annexation_successors':2,'unique_2016_csd_uids':376,'unique_current_2021_target_csd_uids':374,'duplicate_targets':{'5909020':['Skwahla 2 predecessor','Chilliwack original source unit'],'5915075':['Langley 5 predecessor','Maple Ridge original source unit']}},'no_exact_name_case_dispositions':counts,'ambiguous_same_name_cases':{'count':len(ambiguous),'resolved_by_2016_official_geometry':True,'cases':[{'source_shape_id':r['source_shape_id'],'source_name':r['source_name'],'current_candidates':r['same_name_2021_candidates_in_parent_cd'],'selected_2016_csd_uid':r['selected_2016_csd_uid'],'current_csd_uid':r['candidate_2021_csd_uid_from_485'],'source_2016_overlap_pct':r['official_2016_csd_match']['source_covered_pct']} for r in ambiguous]},'extent_findings':{'geoBoundaries_2016_to_official_2016_source_coverage_below_95':len(source_extent),'official_2016_csd_area_covered_by_source_below_95':len(target_extent),'either_direction_below_95':len(either_extent),'official_2016_csd_area_covered_below_50':sum(r['official_2016_csd_match']['csd_covered_pct']<50 for r in rows),'target_coverage_below_95_by_csd_type':dict(sorted(collections.Counter(r['selected_2016_csd_type'] for r in target_extent).items())),'source_extent_case_not_in_original_2021_low_overlap_flags':[r['source_shape_id'] for r in source_extent if not r['inherited_2021_screen_flags']['best_2021_overlap_below_95']],'original_low_overlap_cases_remeasured':len(low),'recomputed_2021_screen_matches_prior_within_0_002pp':33,'official_2016_to_2021_footprint_coverage_below_95_either_way':len(old_new_extent),'those_with_related_table_rows':14,'those_without_related_table_rows':[r['source_shape_id'] for r in old_new_extent if not r['relevant_official_change_table_rows']],'causal_attribution':'Unresolved. Table 1 reports change codes/population but not polygons/areas and warns that it may not include every change. The 2016 digital boundary product includes coastal water; no land-mask attribution is claimed from these overlap figures.'},'scope_limit':'This is a source-vintage administrative crosswalk. It does not reassess settlement completeness, legal/political ownership, boundary authority, land coverage or regional approval.'}
(OUT/'exception-findings.json').write_text(json.dumps({'no_exact_2021_names':name_findings,'ambiguous_2021_names':summary['ambiguous_same_name_cases']['cases'],'low_overlap_2021_geometry_cases':[{'source_shape_id':r['source_shape_id'],'source_name':r['source_name'],'prior_overlap_pct':r['prior_overlap_pct'],'recomputed_overlap_pct':r['recomputed_source_to_2021_candidate_overlap_pct'],'official_2016_csd_uid':r['selected_2016_csd_uid'],'official_2016_to_2021_old_covered_pct':r['official_2016_to_2021_candidate_overlap_2016_covered_pct'],'official_2016_to_2021_new_covered_pct':r['official_2016_to_2021_candidate_overlap_2021_covered_pct'],'table_rows':[e['csv_line'] for e in r['relevant_official_change_table_rows']],'extent_status':r['extent_status']} for r in low],'all_2016_source_target_extent_cases':[{'source_shape_id':r['source_shape_id'],'source_name':r['source_name'],'location_id':r['location_id'],'current_parent_cd_uid':r['current_parent_cd_uid'],'official_2016_csd_uid':r['selected_2016_csd_uid'],'official_2016_csd_name':r['selected_2016_csd_name'],'official_2016_csd_type':r['selected_2016_csd_type'],'source_covered_pct':r['official_2016_csd_match']['source_covered_pct'],'csd_covered_pct':r['official_2016_csd_match']['csd_covered_pct'],'current_2021_csd_uid':r['candidate_2021_csd_uid_from_485'],'current_2021_csd_name':r['candidate_2021_csd_name_from_485'],'baseline_2021_overlap_pct':r['prior_overlap_pct']} for r in either_extent],'additional_2016_extent_cases':[{'source_shape_id':r['source_shape_id'],'source_name':r['source_name'],'official_2016_csd_uid':r['selected_2016_csd_uid'],'source_covered_pct':r['official_2016_csd_match']['source_covered_pct'],'csd_covered_pct':r['official_2016_csd_match']['csd_covered_pct'],'baseline_2021_overlap_pct':r['prior_overlap_pct']} for r in either_extent if not r['inherited_2021_screen_flags']['best_2021_overlap_below_95']]},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
(OUT/'results-summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(json.dumps({'exception_csv_rows':sum(1 for _ in open(OUT/'exception-review.csv',encoding='utf-8'))-1,'flagged_union':58,'source_direction_extent_cases':len(source_extent),'target_direction_extent_cases':len(target_extent),'name_dispositions':counts},indent=2))
